    Z6GameJson(const Z6GameJson& other) : schema_version_(other.schema_version_), schema_version_valid_(other.schema_version_valid_), name_(other.name_), name_valid_(other.name_valid_), level_(other.level_), level_valid_(other.level_valid_), players_(other.players_), players_valid_(other.players_valid_), human_(other.human_), human_valid_(other.human_valid_) {}
    Z6GameJson& operator=(const Z6GameJson& other);

    static bool validate(const std::string& json_str);

    bool getschema_version(int& val) const;
    bool getName(std::string& val) const;
    bool getLevel(int& val) const;
